  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$La demande d'entrée n'est pas un objectif. Le conseiller cherche d'abord les projets de vie et la date de chacun, puis viendra l'étude. Préparer une simulation, comparer des enveloppes ou vérifier la fiscalité revient à raisonner solution avant stratégie (leçon 1).$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q02$academy_seed$, $academy_seed$vrai_faux$academy_seed$, $academy_seed$Recueillir les objectifs de vie et l'horizon de chaque projet$academy_seed$, $academy_seed$Vrai ou faux : noter « long terme » comme horizon, sans date, suffit pour choisir une enveloppe adaptée.$academy_seed$, $academy_seed$["Vrai","Faux"]$academy_seed$::jsonb, 1)
