  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Faux. Un horizon sans date ne permet ni de choisir une enveloppe ni de vérifier plus tard que la stratégie tient. Chaque objectif reçoit une date, même approximative (leçon 1).$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q03$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Recueillir les objectifs de vie et l'horizon de chaque projet$academy_seed$, $academy_seed$Cas fictif. Madame Roux, 45 ans, veut investir 40 000 euros. Elle évoque les études de son fils dans trois ans et sa retraite dans vingt ans. Comment le conseiller traite-t-il la somme ?$academy_seed$, $academy_seed$["Un seul horizon, le plus long, parce qu'il laisse le plus de temps à l'épargne","Deux poches distinctes, l'une à trois ans, l'autre à vingt ans","Un horizon moyen d'une dizaine d'années, pour concilier les deux projets","Attendre que les études soient financées avant d'investir quoi que ce soit"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Deux objectifs, deux horizons, donc deux poches. Un horizon unique, qu'il soit le plus long ou une moyenne, ne correspond à aucun des deux projets et expose la poche études à un risque inadapté (leçon 1).$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q04$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Recueillir les objectifs de vie et l'horizon de chaque projet$academy_seed$, $academy_seed$Un client refuse de préciser ses objectifs d'investissement et demande simplement « ce qui rapporte le mieux ». Que fait le conseiller en investissements financiers selon le code monétaire et financier ?$academy_seed$, $academy_seed$["Il recommande une solution prudente par défaut","Il s'abstient de recommander l'opération et le consigne","Il recommande en précisant que c'est sous réserve des objectifs","Il applique le profil le plus courant de sa clientèle"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$L'article L541-8-1 du code monétaire et financier prévoit que, lorsque le client ne communique pas les informations requises, le conseiller s'abstient de recommander. Ni une solution par défaut ni une réserve ne remplacent l'information manquante (leçon 1).$academy_seed$);
