  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 2, $academy_seed$Le besoin de liquidité à douze mois est connu et il n'existe aucune réserve. Le PER est en principe bloqué, et des unités de compte rachetables exposent la somme à un risque de perte juste avant une échéance. Seule la troisième organisation respecte l'ordre précaution, projet, long terme (leçon 2).$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l2, $academy_seed$q07$academy_seed$, $academy_seed$vrai_faux$academy_seed$, $academy_seed$Établir la situation financière et le besoin de liquidité$academy_seed$, $academy_seed$Vrai ou faux : un contrat d'assurance vie étant rachetable, la somme investie est disponible immédiatement et sans conséquence.$academy_seed$, $academy_seed$["Vrai","Faux"]$academy_seed$::jsonb, 2)
